Первая проверка готова. Допиши условия во второй и третьей и итоговую строку:

```swift
func registrationMessage(name: String?, password: String?, age: Int?) -> String {
    guard let name, !name.isEmpty else {
        return "Введите имя"
    }

    guard let password, password.count >= ___ else {
        return "Пароль должен быть не короче 8 символов"
    }

    guard let age, ___ else {
        return "Регистрация доступна с 14 лет"
    }

    return "Аккаунт создан: \(___), \(___)"
